<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>VAPO: Value-Model-Based RL for Advanced Reasoning</title>

    <!-- Fonts: technical/scientific feel -->
    <link rel="stylesheet" href="https://api.fontshare.com/v2/css?f[]=clash-display@600,700&f[]=satoshi@400,500,700&display=swap">

    <style>
        /* ===========================================
           CSS CUSTOM PROPERTIES (THEME)
           Dark technical theme for ML researchers
           =========================================== */
        :root {
            /* Colors — deep navy/charcoal with cyan accent */
            --bg-primary: #0a0f1c;
            --bg-secondary: #111827;
            --bg-card: #1a2332;
            --text-primary: #f0f4f8;
            --text-secondary: #9ca3af;
            --accent: #00d4ff;
            --accent-secondary: #7c3aed;
            --accent-glow: rgba(0, 212, 255, 0.2);
            --success: #10b981;
            --warning: #f59e0b;
            --danger: #ef4444;

            /* Typography — MUST use clamp() */
            --font-display: 'Clash Display', sans-serif;
            --font-body: 'Satoshi', sans-serif;
            --title-size: clamp(1.75rem, 5vw, 3.5rem);
            --h2-size: clamp(1.25rem, 3.5vw, 2.25rem);
            --h3-size: clamp(1rem, 2vw, 1.5rem);
            --body-size: clamp(0.75rem, 1.4vw, 1.1rem);
            --small-size: clamp(0.65rem, 1vw, 0.85rem);

            /* Spacing — MUST use clamp() */
            --slide-padding: clamp(1.5rem, 4vw, 4rem);
            --content-gap: clamp(0.75rem, 2vw, 1.5rem);
            --element-gap: clamp(0.25rem, 1vw, 0.75rem);

            /* Animation */
            --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
            --duration-normal: 0.6s;
        }

        /* ===========================================
           BASE STYLES
           =========================================== */
        * { margin: 0; padding: 0; box-sizing: border-box; }

        html, body {
            height: 100%;
            overflow-x: hidden;
        }

        html {
            scroll-snap-type: y mandatory;
            scroll-behavior: smooth;
        }

        /* ===========================================
           SLIDE BASE STYLES (from viewport-base.css)
           =========================================== */
        .slide {
            width: 100vw;
            height: 100vh;
            height: 100dvh;
            overflow: hidden;
            scroll-snap-align: start;
            display: flex;
            flex-direction: column;
            position: relative;
            background: var(--bg-primary);
        }

        .slide-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            justify-content: center;
            max-height: 100%;
            overflow: hidden;
            padding: var(--slide-padding);
        }

        /* ===========================================
           TYPOGRAPHY
           =========================================== */
        h1 {
            font-family: var(--font-display);
            font-size: var(--title-size);
            font-weight: 700;
            color: var(--text-primary);
            line-height: 1.1;
            margin-bottom: var(--content-gap);
        }

        h2 {
            font-family: var(--font-display);
            font-size: var(--h2-size);
            font-weight: 600;
            color: var(--text-primary);
            line-height: 1.2;
            margin-bottom: var(--content-gap);
        }

        h3 {
            font-family: var(--font-body);
            font-size: var(--h3-size);
            font-weight: 500;
            color: var(--accent);
            margin-bottom: var(--element-gap);
        }

        p, li {
            font-family: var(--font-body);
            font-size: var(--body-size);
            color: var(--text-secondary);
            line-height: 1.5;
        }

        .highlight {
            color: var(--accent);
            font-weight: 500;
        }

        .big-number {
            font-family: var(--font-display);
            font-size: clamp(3rem, 10vw, 8rem);
            font-weight: 700;
            color: var(--accent);
            line-height: 1;
        }

        /* ===========================================
           ANIMATIONS
           =========================================== */
        .reveal {
            opacity: 0;
            transform: translateY(30px);
            transition: opacity var(--duration-normal) var(--ease-out-expo),
                        transform var(--duration-normal) var(--ease-out-expo);
        }

        .slide.visible .reveal {
            opacity: 1;
            transform: translateY(0);
        }

        .reveal:nth-child(1) { transition-delay: 0.1s; }
        .reveal:nth-child(2) { transition-delay: 0.2s; }
        .reveal:nth-child(3) { transition-delay: 0.3s; }
        .reveal:nth-child(4) { transition-delay: 0.4s; }
        .reveal:nth-child(5) { transition-delay: 0.5s; }
        .reveal:nth-child(6) { transition-delay: 0.6s; }

        /* ===========================================
           SLIDE 1: TITLE
           =========================================== */
        .title-slide {
            background:
                radial-gradient(ellipse at 30% 70%, rgba(124, 58, 237, 0.15) 0%, transparent 50%),
                radial-gradient(ellipse at 70% 30%, rgba(0, 212, 255, 0.1) 0%, transparent 50%),
                var(--bg-primary);
        }

        .title-slide .slide-content {
            align-items: center;
            text-align: center;
        }

        .title-slide h1 {
            max-width: 90vw;
        }

        .subtitle {
            font-family: var(--font-body);
            font-size: var(--h3-size);
            color: var(--text-secondary);
            margin-bottom: var(--content-gap);
        }

        .badge-row {
            display: flex;
            gap: var(--element-gap);
            flex-wrap: wrap;
            justify-content: center;
            margin-top: var(--content-gap);
        }

        .badge {
            background: var(--bg-card);
            border: 1px solid rgba(0, 212, 255, 0.3);
            border-radius: 4px;
            padding: clamp(0.4rem, 1vw, 0.75rem) clamp(0.75rem, 2vw, 1.25rem);
            font-family: var(--font-body);
            font-size: var(--small-size);
            color: var(--text-secondary);
        }

        .badge.accent {
            background: rgba(0, 212, 255, 0.1);
            border-color: var(--accent);
            color: var(--accent);
        }

        .authors {
            font-family: var(--font-body);
            font-size: var(--body-size);
            color: var(--text-secondary);
            margin-top: var(--content-gap);
        }

        /* ===========================================
           SLIDE 2-9: CONTENT SLIDES
           =========================================== */
        .content-slide {
            background: var(--bg-primary);
        }

        .slide-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            margin-bottom: var(--content-gap);
            padding-bottom: var(--element-gap);
            border-bottom: 1px solid rgba(255,255,255,0.1);
        }

        .slide-number {
            font-family: var(--font-display);
            font-size: var(--small-size);
            color: var(--accent);
            opacity: 0.7;
        }

        /* ===========================================
           COMPARISON LAYOUTS
           =========================================== */
        .two-column {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: var(--content-gap);
            flex: 1;
        }

        .three-column {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: var(--content-gap);
            flex: 1;
        }

        @media (max-width: 768px) {
            .two-column, .three-column {
                grid-template-columns: 1fr;
            }
        }

        /* ===========================================
           CHALLENGE CARDS (Slide 3)
           =========================================== */
        .challenge-card {
            background: var(--bg-card);
            border-radius: 8px;
            padding: var(--content-gap);
            border-left: 3px solid var(--accent-secondary);
        }

        .challenge-card h3 {
            color: var(--accent-secondary);
            margin-bottom: var(--element-gap);
        }

        .challenge-card p {
            font-size: var(--small-size);
        }

        /* ===========================================
           FRAMEWORK DIAGRAM (Slide 4)
           =========================================== */
        .framework-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            grid-template-rows: auto auto;
            gap: var(--element-gap);
            flex: 1;
        }

        .framework-item {
            background: var(--bg-card);
            border-radius: 6px;
            padding: clamp(0.5rem, 1.5vw, 1rem);
            text-align: center;
        }

        .framework-item.full-width {
            grid-column: 1 / -1;
            background: linear-gradient(90deg, rgba(0,212,255,0.1), rgba(124,58,237,0.1));
            border: 1px solid rgba(0,212,255,0.2);
        }

        .framework-item h4 {
            font-family: var(--font-body);
            font-size: var(--small-size);
            color: var(--accent);
            margin-bottom: 0.25rem;
        }

        .framework-item p {
            font-size: clamp(0.55rem, 0.9vw, 0.75rem);
            color: var(--text-secondary);
        }

        .challenge-label {
            font-family: var(--font-body);
            font-size: var(--small-size);
            color: var(--text-secondary);
            text-align: center;
            padding: var(--element-gap);
        }

        /* ===========================================
           GAE VISUAL (Slide 5)
           =========================================== */
        .gae-visual {
            display: flex;
            align-items: center;
            justify-content: space-around;
            gap: var(--content-gap);
            padding: var(--content-gap) 0;
        }

        .gae-bar-container {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: var(--element-gap);
        }

        .gae-bar {
            width: clamp(40px, 8vw, 80px);
            background: var(--bg-card);
            border-radius: 4px;
            display: flex;
            align-items: flex-end;
            justify-content: center;
            padding: 4px;
        }

        .gae-bar-fill {
            background: linear-gradient(to top, var(--accent), var(--accent-secondary));
            border-radius: 3px;
            width: 100%;
            transition: height 0.8s var(--ease-out-expo);
        }

        .gae-label {
            font-family: var(--font-body);
            font-size: var(--small-size);
            color: var(--text-secondary);
            text-align: center;
        }

        .gae-label strong {
            color: var(--text-primary);
        }

        /* ===========================================
           BAR CHART (Slide 6)
           =========================================== */
        .bar-chart {
            display: flex;
            align-items: flex-end;
            justify-content: center;
            gap: var(--content-gap);
            height: min(55vh, 400px);
            padding: var(--content-gap);
            background: var(--bg-card);
            border-radius: 8px;
            margin-top: var(--element-gap);
        }

        .bar-group {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: var(--element-gap);
            flex: 1;
            max-width: 150px;
        }

        .bar {
            width: 100%;
            background: linear-gradient(to top, var(--accent-secondary), var(--accent));
            border-radius: 4px 4px 0 0;
            display: flex;
            align-items: flex-start;
            justify-content: center;
            padding-top: 0.5rem;
            transition: height 1s var(--ease-out-expo);
        }

        .bar-label {
            font-family: var(--font-body);
            font-size: var(--small-size);
            color: var(--text-secondary);
            text-align: center;
            word-break: break-word;
        }

        .bar-value {
            font-family: var(--font-display);
            font-size: clamp(0.875rem, 1.5vw, 1.25rem);
            font-weight: 700;
            color: var(--text-primary);
        }

        .bar.highlight-bar {
            background: linear-gradient(to top, var(--accent), #00ffcc);
            box-shadow: 0 0 30px var(--accent-glow);
        }

        .chart-source {
            font-size: var(--small-size);
            color: var(--text-secondary);
            margin-top: var(--content-gap);
            text-align: center;
        }

        /* ===========================================
           TRAINING CURVE (Slide 7)
           =========================================== */
        .curve-container {
            display: flex;
            gap: var(--content-gap);
            flex: 1;
            align-items: stretch;
        }

        .curve-image {
            flex: 1;
            background: var(--bg-card);
            border-radius: 8px;
            display: flex;
            align-items: center;
            justify-content: center;
            overflow: hidden;
        }

        .curve-image img {
            max-width: 100%;
            max-height: 100%;
            object-fit: contain;
        }

        .curve-stats {
            display: flex;
            flex-direction: column;
            gap: var(--element-gap);
            justify-content: center;
            min-width: 200px;
        }

        .stat-card {
            background: var(--bg-card);
            border-radius: 6px;
            padding: var(--element-gap) var(--content-gap);
        }

        .stat-card h4 {
            font-family: var(--font-body);
            font-size: var(--small-size);
            color: var(--text-secondary);
            margin-bottom: 0.25rem;
        }

        .stat-card .value {
            font-family: var(--font-display);
            font-size: var(--h2-size);
            color: var(--accent);
        }

        .stat-card .subtext {
            font-size: var(--small-size);
            color: var(--text-secondary);
        }

        /* ===========================================
           ABLATION TABLE (Slide 8)
           =========================================== */
        .ablation-container {
            flex: 1;
            display: flex;
            flex-direction: column;
            gap: var(--element-gap);
        }

        .ablation-row {
            display: grid;
            grid-template-columns: 2fr 1fr 2fr;
            gap: var(--content-gap);
            align-items: center;
            padding: var(--element-gap) 0;
            border-bottom: 1px solid rgba(255,255,255,0.05);
        }

        .ablation-row.header {
            border-bottom: 2px solid rgba(0,212,255,0.3);
            padding-bottom: var(--element-gap);
        }

        .ablation-component {
            font-family: var(--font-body);
            font-size: var(--body-size);
            color: var(--text-primary);
        }

        .ablation-score {
            font-family: var(--font-display);
            font-size: var(--h3-size);
            color: var(--accent);
            text-align: center;
        }

        .ablation-bar-container {
            background: var(--bg-card);
            border-radius: 4px;
