            font-size: var(--small-size);
            color: var(--danger);
            font-style: italic;
        }

        /* ===========================================
           TAKEAWAYS (Slide 9)
           =========================================== */
        .takeaway-list {
            display: flex;
            flex-direction: column;
            gap: var(--content-gap);
            flex: 1;
            justify-content: center;
        }

        .takeaway-item {
            display: flex;
